mapper.select:
select count(*) from appointment
where patient_id = #{patientId}
  and status != 'cancelled'
  and appointment_time >= #{dayStart}
  and appointment_time < #{dayEnd}

select count(*) from appointment
where patient_id = #{patientId}
  and schedule_id = #{scheduleId}
  and status != 'cancelled'

SELECT a.id AS appointmentId, p.id AS patientId, p.name AS patientName, p.phone_number AS phoneNumber, p.id_card_number AS idCardNumber, p.specific_role AS specificRole, a.appointment_time AS appointmentTime, a.status AS status, CASE a.status WHEN 'scheduled' THEN '待就诊' WHEN 'completed' THEN '已完成' WHEN 'cancelled' THEN '已取消' ELSE a.status END AS statusName, a.fee AS fee, a.actual_fee AS actualFee, a.source_type AS sourceType, a.created_at AS createdAt, s.id AS scheduleId, s.schedule_date AS scheduleDate, s.time_slot AS timeSlot, CASE s.time_slot WHEN 'morning' THEN '上午' WHEN 'afternoon' THEN '下午' WHEN 'evening' THEN '晚上' ELSE s.time_slot END AS timeSlotName FROM appointment a JOIN patient p ON a.patient_id = p.id JOIN schedule s ON a.schedule_id = s.id WHERE a.doctor_id = #{doctorId} AND s.schedule_date = DATE(#{date}) AND a.status != 'cancelled'
AND s.time_slot = #{timeSlot}
ORDER BY a.appointment_time ASC
